cd /work/output/artifacts/skill-flow-ixp-routing-negative/sf-update/SfUpdateSolution/SfUpdate \
  && uip maestro flow node configure "SfUpdate.flow" "listOpenOpportunities1" \
    --detail '{
      "connectionId": "0fddf20e-f229-4ee9-acb3-c5be50034839",
      "folderKey": "5da18ec0-7de1-4e57-aaf1-ddc8a369c199",
      "objectName": "Opportunity",
      "method": "GET",
      "endpoint": "/Opportunity",
      "queryParameters": {
        "fields": "Id,Name,StageName,CloseDate",
        "filter": "IsClosed eq false"
      }
    }' --output json 2>/dev/null \
  && uip maestro flow node configure "SfUpdate.flow" "updateOpportunityStage1" \
    --detail '{
      "connectionId": "0fddf20e-f229-4ee9-acb3-c5be50034839",
      "folderKey": "5da18ec0-7de1-4e57-aaf1-ddc8a369c199",
      "objectName": "Opportunity",
      "method": "PATCH",
      "endpoint": "/Opportunity/{opportunityId}",
      "pathParameters": {
        "opportunityId": "=js:$vars.loop1.currentItem.Id"
      },
      "bodyParameters": {
        "StageName": "Closed Won"
      }
    }' --output json 2>/dev/null \
  && uip maestro flow validate "SfUpdate.flow" --output json 2>/dev/null \
  && uip maestro flow format "SfUpdate.flow" --output json 2>/dev/null

